# define ZEPHIR_ZSTR_FMT "%pS"
# define ZEPHIR_ZSTR_ARG(str) (str)
#else
# define ZEPHIR_ZSTR_FMT "%s"
# define ZEPHIR_ZSTR_ARG(str) ZSTR_VAL(str)
#endif

#define RETURN_ON_FAILURE(what) \
	do { \
		if (what == FAILURE) { \
			return; \
		} \
	} while (0)

#define RETURN_MM_ON_FAILURE(what) \
	do { \
		if (what == FAILURE) { \
			return; \
		} \
	} while (0)

/** Return null restoring memory frame */
#define RETURN_MM_NULL()            { RETVAL_NULL(); ZEPHIR_MM_RESTORE(); return; }

