static PHP_MSHUTDOWN_FUNCTION(phalcon)
{
#ifndef ZEPHIR_RELEASE
	
	zephir_deinitialize_memory();
#endif
	UNREGISTER_INI_ENTRIES();
	zephir_module_shutdown();
	return SUCCESS;
}

static void php_zephir_init_globals(zend_phalcon_globals *phalcon_globals)
{
	phalcon_globals->initialized = 0;

	/* Cache Enabled */
	phalcon_globals->cache_enabled = 1;

	/* Recursive Lock */
	phalcon_globals->recursive_lock = 0;

	/* Static cache */
	memset(phalcon_globals->scache, '\0', sizeof(zephir_fcall_cache_entry*) * ZEPHIR_MAX_CACHE_SLOTS);

	/* Inline property cache (per-request reset defeats stale-ce/ABA reuse) */
	memset(phalcon_globals->pcache, '\0', sizeof(void*) * ZEPHIR_MAX_PROPERTY_CACHE_SLOTS * ZEPHIR_PROPERTY_CACHE_SLOT_SIZE);

	phalcon_globals->orm.ast_cache = NULL;
	phalcon_globals->orm.parser_cache = NULL;
	
}

static void php_zephir_init_module_globals(zend_phalcon_globals *phalcon_globals)
{
	/* No request yet: a call site's inline cache starts zeroed, so it never matches */
	phalcon_globals->request_number = 0;
	phalcon_globals->orm.zephir_owned_resultset_prefetch_records = NULL;
}

static void zephir_init_static_properties_Phalcon_Filter_Validation();
static void zephir_init_static_properties_Phalcon_Mvc_Model_Hydration_GetPrivateProperties();
static PHP_RINIT_FUNCTION(phalcon)
{
	zend_phalcon_globals *phalcon_globals_ptr;
	phalcon_globals_ptr = ZEPHIR_VGLOBAL;

	php_zephir_init_globals(phalcon_globals_ptr);
	phalcon_globals_ptr->request_number++;
	zephir_ini_activate_globals(zephir_request_ini_entries);
	zephir_initialize_memory(phalcon_globals_ptr);

		zephir_init_static_properties_Phalcon_Filter_Validation();
		zephir_init_static_properties_Phalcon_Mvc_Model_Hydration_GetPrivateProperties();
	
	return SUCCESS;
}

static PHP_RSHUTDOWN_FUNCTION(phalcon)
{
	phalcon_orm_destroy_cache();
	zephir_globals_release_hash(&ZEPHIR_GLOBAL(orm).ast_cache);
	zephir_globals_release_hash(&ZEPHIR_GLOBAL(orm).parser_cache);
	zephir_deinitialize_memory();
	return SUCCESS;
}



static PHP_MINFO_FUNCTION(phalcon)
{
	php_info_print_box_start(0);
	php_printf("%s", PHP_PHALCON_DESCRIPTION);
	php_info_print_box_end();

	php_info_print_table_start();
	php_info_print_table_header(2, PHP_PHALCON_NAME, "enabled");
	php_info_print_table_row(2, "Author", PHP_PHALCON_AUTHOR);
	php_info_print_table_row(2, "Version", PHP_PHALCON_VERSION);
	php_info_print_table_row(2, "Build Date", __DATE__ " " __TIME__ );
	php_info_print_table_row(2, "Powered by Zephir", "Version " PHP_PHALCON_ZEPVERSION);
	php_info_print_table_end();
	
	DISPLAY_INI_ENTRIES();
}

static PHP_GINIT_FUNCTION(phalcon)
{
#if defined(COMPILE_DL_PHALCON) && defined(ZTS)
	ZEND_TSRMLS_CACHE_UPDATE();
#endif

	php_zephir_init_globals(phalcon_globals);
	php_zephir_init_module_globals(phalcon_globals);
}

static PHP_GSHUTDOWN_FUNCTION(phalcon)
{
	zephir_globals_release_string(&phalcon_globals->orm.zephir_owned_resultset_prefetch_records);
}


